public async Task<IReadOnlyList<VectorSearchResult>> SearchWithFilterAsync(
    string query,
    string? tenantId,
    string? category,
    CancellationToken ct = default)
{
    var queryVector = await _embedder.EmbedAsync(new[] { query }, ct);

    var filters = new Dictionary<string, object?>(StringComparer.OrdinalIgnoreCase)
    {
        ["tenantId"] = tenantId,
        ["category"] = category
    };

    return await _store.SearchAsync(
        queryVector[0].Vector,
        topK: 8,
        filters: filters,
        ct);
}
